import fs from 'node:fs/promises';
import path from 'node:path';
const root=process.cwd();
const a=JSON.parse(await fs.readFile(path.join(root,'outputs/catalog-foundation-analysis-20261111.json'),'utf8'));
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const css='body{font:14px/1.5 system-ui;margin:24px;color:#203040}table{border-collapse:collapse;width:100%}td,th{border:1px solid #d2dce5;padding:9px;vertical-align:top}th{background:#e7eef5;position:sticky;top:0}a{color:#075da8}input,select{padding:9px;margin:8px 10px 16px 0}small{color:#596b7b}code{overflow-wrap:anywhere}details{max-width:650px}li{margin:5px 0}';
const itemMap=new Map(a.inventory.map(p=>[p.id,p]));
const categories=new Map(a.categories.map(c=>[Number(c.id),c.name]));
const commonStart=(title,description)=>'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><style>'+css+'</style><h1>'+esc(title)+'</h1><p>'+description+'</p><p><a href="../docs/catalog-foundation-stage1-20261111.html">Спецификация этапа 1</a> · Снимок '+esc(a.generated_at)+'</p>';
const rows=a.inventory.map(p=>'<tr data-visible="'+(p.visibility==='show'?'yes':'no')+'" data-issues="'+(p.problems.length?'yes':'no')+'"><td>'+p.id+'<br>'+esc(p.sku)+'</td><td>'+esc(p.name)+'<br><small>'+esc(p.category)+'; '+esc(p.visibility)+'; свободный остаток по CatalogSelection: '+p.stock+'</small></td><td>'+esc(p.effective_h1)+'<details><summary>Итоговое SEO</summary><p>Title: '+esc(p.effective_title)+'</p><p>Meta Description: '+esc(p.effective_description)+'</p><p>Источник H1: '+esc(p.h1_source)+' (приоритетное поле — не доказательство ручного ввода)</p></details></td><td>'+p.attribute_rows+' / '+p.filter_rows+'</td><td>'+(p.problems.length?'<ul>'+p.problems.map(i=>'<li><code>'+esc(i.code)+'</code>: '+esc(i.detail)+'</li>').join('')+'</ul>':'Нет срабатываний проверенных правил')+'</td></tr>').join('');
const filters='<label>Поиск по SKU, названию, категории или проблеме <input id="q" type="search"></label><label>Видимость <select id="visibility"><option value="">Все</option><option value="yes">Видимые</option><option value="no">Скрытые</option></select></label><label>Проверки <select id="issues"><option value="">Все</option><option value="yes">Есть срабатывания</option><option value="no">Нет срабатываний</option></select></label><p id="count" role="status"></p>';
const script='<script>const rows=[...document.querySelectorAll("tbody tr")];const q=document.getElementById("q"),v=document.getElementById("visibility"),i=document.getElementById("issues");function apply(){let n=0;for(const r of rows){const show=r.textContent.toLocaleLowerCase("ru").includes(q.value.toLocaleLowerCase("ru"))&&(!v.value||r.dataset.visible===v.value)&&(!i.value||r.dataset.issues===i.value);r.hidden=!show;if(show)n++;}document.getElementById("count").textContent="Показано: "+n+" из "+rows.length;}for(const el of[q,v,i])el.addEventListener("input",apply);apply();</script>';
const doc=commonStart('Обследование всех 1 184 товаров','Срабатывания — очередь проверки, не рейтинг плохих карточек. Услугам не нужны шинные свойства; отсутствие собственного content не означает отсутствие текста InSEO; пропуск PR у цельнолитой допустим. Размеры фото проверены по серверным файлам, не визуально. Никакие товарные данные не изменены.')+filters+'<table><thead><tr><th>ID / SKU</th><th>Товар</th><th>Итоговый H1 / SEO</th><th>Характеристики / фильтры</th><th>Проверки</th></tr></thead><tbody>'+rows+'</tbody></table>'+script+'</html>';
await fs.writeFile(path.join(root,'outputs/catalog-foundation-products-20261111.html'),doc);
const labels={attribute_only:'Только характеристика',filter_only:'Только фильтр',needs_review:'Различается: проверить'};
const cr=a.comparison.map(c=>'<tr><td>'+c.product_id+'<br>'+esc(c.sku)+'</td><td>'+esc(itemMap.get(Number(c.product_id))?.name)+'<br><small>'+esc(categories.get(Number(c.category_id)))+'</small></td><td>'+esc(c.code)+'</td><td>'+esc(labels[c.state])+'</td><td>'+c.attribute_values.map(esc).join('<br>')+'</td><td>'+c.filter_values.map(esc).join('<br>')+'</td></tr>').join('');
const conflictDoc=commonStart('Расхождения характеристик и фильтров','Это не список однозначных ошибок. Равнозначные покрытия, несколько совместимых размеров, радиальные/диагональные обозначения и альтернативные размеры нужно разбирать по профилю и источнику. Сравнение использует ограниченную нормализацию; точные совпадения исключены. Строки показывают, где нельзя переносить данные вслепую.')+'<p>'+a.comparison.length+' наблюдений; один товар может иметь несколько строк.</p><table><thead><tr><th>ID / SKU</th><th>Товар</th><th>Будущее свойство</th><th>Состояние</th><th>Характеристики</th><th>Фильтры</th></tr></thead><tbody>'+cr+'</tbody></table></html>';
await fs.writeFile(path.join(root,'outputs/catalog-foundation-conflicts-20261111.html'),conflictDoc);
if(a.inventory.length!==a.counts.products)throw new Error('Product count mismatch');
if(a.categories.reduce((n,c)=>n+c.total,0)!==a.counts.products)throw new Error('Category counts mismatch');
if(a.inventory.some(p=>!Number.isFinite(p.stock)))throw new Error('Invalid stock');
if(!a.inventory.every(p=>p.id&&typeof p.effective_h1==='string'))throw new Error('Invalid item');
console.log(JSON.stringify({product_rows:a.inventory.length,comparison_rows:a.comparison.length,checks:'counts, category totals, stock values and item structure OK'}));
